.uploadSteps {
  &__wrapper {
    display: flex;
    justify-content: center;
  }

  width: 900px;

  &__tabs {
    width: 75%;
    margin: 0 auto $m-lg;
    text-align: center;
  }

  &__content {
    .paging-group {
      margin-top: $m-base;
    }
  }

  &__uploader {
    display: flex;

    > .dropzone {
      flex: 1 1 auto;
    }

    > .dropResults {
      flex: 0 1 auto;
      padding-left: $padding-x-base;
    }
  }
}

.dropResults {
  .kpi-upload__upload-files-list {
    display: inline-block;
  }
}

@include triple-growCenter('.dropItem', inline-flex, 5px);
.dropItem {
  &__row {
    display: flex; // to remove line spacing for inline-flex children's
    & + & {
      margin-top: 10px;
    }
  }
}

.uploadedCols {
  &.panel--bordered {
    &, .panel__heading,
    .panel__body,
    .panel__body + .panel__body {
      border-color: $gray-new-light;
    }
  }
  > .panel__heading [class*="col"] {
    padding-top: $grid-gutter-width / 2.5;
    padding-bottom: $grid-gutter-width / 2.5;
  }

  &__opt {
    display: flex;
    align-items: center;
    @include panelStyle();
    @include form-control-size();
    background: $color-base-0;

    .col-auto {
      display: flex;
    }
  }
}


