/*!*DROPDOWN - ARROW ALL*/
$triangleSize: 13px;
$triangleSizeInner: $triangleSize - 1px;
$trianglePosLeft: 17px;

[class*="dropdown-kit--"] {
  position: relative;

  .dropdown-content:not(.dropdown-content-tooltip) {
    min-width: 100%;
    width: auto !important;
  }
}
.dropdown-button.active,
[class*="dropdown-kit--"] .dropdown-button.active {
  position: relative;
}

[class*="dropdown-kit--arrow--"] {
  > .dropdown-button {
    position: relative;
    &:before, &:after {
      display: block;
      position: absolute;
      width: 0;
      height: 0;
      border-style: solid;
      color: transparent;
      opacity: 0;

    }

    &:before {
      border-width: $triangleSize;
    }
    &:after {
      border-width: $triangleSizeInner;
      z-index: 100; //May overlap the .dropdown-content > icons
      //z-index: 1030; // to override the dropdown content if .dropdown-content will be higher > see dropdwon.scss
    }
    &:before {
      z-index: 0;
    }

    &.active {
      &:before, &:after {
        content: '';
        opacity: 1;
        animation: arrowOpacity .3s ease;
      }
    }
  }
}

@keyframes arrowOpacity {
  0% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}


/*DROPDOWN - ARROW BELOW*/
.dropdown-kit--arrow--below:not(.dropdown-kit--arrow--below--reverse) > .dropdown-content, //Shold be specified for > child, cause list can include another .dropdown-content
.dropdown-kit--below .dropdown-content {
  top: 100% !important;

  .dropdown-content {
    top: 0 !important;
    margin-top: 0 !important;
  }
}
.dropdown-kit--arrow--below:not(.dropdown-kit--arrow--below--reverse) {
  .dropdown-content {
    margin-top: $triangleSizeInner; //https://i.imgur.com/ORFcBZP.png
    .group-box__item-content & {
      margin-top: calc(#{$triangleSizeInner} - #{$control-border-width}); //https://i.imgur.com/LYsJ9nU.png
    }
    .wg_canban__user-notes & {
      margin-top: 16px;
    }

    .main-dir__documents & {
      margin-top: 10px;
    }
    .main-directories__sublink > & {
      margin-top: 0; //https://prnt.sc/13b74mv
    }

    .dropdown-content {
      margin-top: 0;
    }
  }
  > .dropdown-button {
    &:before, &:after {
      top: 90%;
    }
    &.active {
      &:before, &:after {
        top: 100%;
      }
    }
  }
}
.dropdown-kit--arrow--below {
  > .dropdown-button {
    &:before, &:after {
      left: 50%;
      transform: translateX(-50%);
      transition: top .3s ease;
    }
    &:before {
      //margin-left: -$trianglePosLeft;
    }
    &:after {
      //margin-left: -($trianglePosLeft - 1);
    }
    .main-dir__documents & {
      &:before {
        margin-top: -18px; //https://prnt.sc/pgz3qc
      }
      &:after {
        margin-top: -17px; //https://prnt.sc/pgz3qc
      }
    }
  }
  .dropdown-button {
    &:before {
      margin-top: -8px;
      border-bottom-color: $dropdown-border-color;
    }
    &:after {
      margin-top: -7px;
      border-bottom-color: #fff;
    }
  }
  .dropdown-content-tooltip {
    margin-left: 20px;
    .gts-trace & {
      margin-left: 0;
    }
  }
  .gts-trace > & {
    &:last-child {
      .dropdown-content-tooltip {
        margin-left: -20px; //https://prnt.sc/q49jdf
        white-space: normal;
      }
    }
  }
}

.dropdown-kit--arrow--below--reverse {
  .dropdown-content {
    top: auto !important;
    bottom: 100% !important;

    .wg_canban__user-notes & {
      margin-bottom: 10px;

    }
  }
  > .dropdown-button {
    &:before, &:after {
      bottom: 90%;

      .wg_canban__user-notes & { //https://prnt.sc/rbgajn
        bottom: auto !important;
        top: -10px;
      }
    }
    &:before {
      margin-top: -6px;
      .wg_canban__user-notes & {

      }
    }
    &.active {
      &:before, &:after {
        bottom: 100%;
      }
    }

  }
}

/* \ DROPDOWN - ARROW BELOW*/


/*  DROPDOWN - ARROW TOP*/
.dropdown-kit--arrow--top {
  > .dropdown-button {
    &:after {
      margin-top: -18px;
      border-top-color: #fff;
    }
    > .dropdown-content {
      top: auto !important;
      bottom: 100%;
      margin-bottom: 18px;
    }
  }
}
/* \ DROPDOWN - ARROW TOP*/


/* DROPDOWN - ARROW RIGHT*/

.dropdown-kit--arrow--right {
  .dropdown-content-tooltip {
    top: -30px !important;
    right: 100% !important;
    left: auto !important;
    margin-right: 31px;
  }
  .dropdown-button {
    &:before, &:after {
      top: 50%;
      right: 100%;
      margin-top: -17px;
    }
    &:before {
      border-left-color: rgba(51, 51, 51, 0.07);
    }
    &:after {
      border-left-color: #fff;
    }
  }
}

.dropdown-kit--light {}

/* DROPDOWN - ARROW LEFT */
.dropdown-kit--arrow--left {
  .dropdown-content {
    top: -30px !important;
    left: 100% !important;
    margin-left: 21px;
  }
  .dropdown-button {
    &:before, &:after {
      top: 50%;
      left: 100%;
      margin-top: -17px;
      margin-left: -10px;
    }
    &:before {
      border-right-color: rgba(51, 51, 51, 0.07);
    }
    &:after {
      border-right-color: #fff;
    }
  }
}

/* \ DROPDOWN - ARROW RIGHT*/

.dropdown-kit--edge-in .dropdown-content {
  left: 0;
  right: 0;
  width: auto !important;
  min-width: inherit;
}

.dropdown-kit--left .dropdown-content {
  width: auto !important;
  right: 100% !important;
  left: auto !important;
}