.ficon--upload:before {
  @extend .ficon--download:before;
  transform: rotate(180deg);
}

.ficon--equalizer {
  transform: rotate(90deg);
}

// SPLIT ICONS
[class^="ficon--"].ficon-shared {
  position: relative;
  &:after {
    @extend .ficon--;
    @extend .ficon--globe:before;
    font-size: .5em;
    color: #028bff;
    color: #659bc8;
    position: absolute;
    z-index: 2;
    top: -0.4em;
    left: -0.4em;
    background-color: #fff;
    border-radius: 50%;
    //text-shadow: 3px 3px 0 #028bff, -1px -1px 0 #028bff, 1px -1px 0 #028bff, -1px 1px 0 #028bff, 1px 1px 0 #028bff;
    //-webkit-text-stroke: 1px #028bff;
  }
}

.ficon--file-text2 {
  position: relative;
  &:before {
    @extend .ficon--file-background:before;
    color: $gray-new-light;
  }
  &:after {
    @extend .ficon--file-lines:before;
    position: absolute;
    top: 0.6em;
    left: 0.3em;
    font-size: 0.5em;
  }
}

