$svgSizeBase: 18px;

//SVG ICONS
// SVG ICONS STYLE
svg {
  fill: none;

  &[class*="icon--"],
  //svg sizes
  .frame__support &,
  .gwt-ScrollTable &,
  .btn &,
  .btn-small &,
  .btn-medium &,
  .operPanel &,
  //.frame__modules &,
  .frame__nav &,
  .page-opers &,
  .frame__info & {
    width: $svgSizeBase;
    height: $svgSizeBase;
    max-height: 100%;
  }
  .btn-large & {
    width: $svgSizeBase * 1.33;
    height: $svgSizeBase * 1.33;
    max-height: 100%;
  }

  .input-group & {
    width: 16px;
    height: 16px;
  }
  .frame__header & {
    width: 20px;
    height: 20px;
  }
  &.icon--sliders {
    .operPanel--header & {
      height: 23px;
    }
  }
  &.icon--barChart { // for operPanel Kanban icon
    width: ($svgSizeBase + 2px);
    height: ($svgSizeBase + 2px);
  }
  &.icon--more {
    width: 25px;
  }

  //svg colors
  &[class*="icon--"],
  .input-group &,
  .frame__support &,
  .gwt-ScrollTable &,
  .btn &,
  .btn-small &,
  .btn-medium &,
  .btn-large &,
  .operPanel .searchForm &,
  .operPanel .btn:not(.btn--circle) &,
  .frame__header &,
  .frame__modules &,
  .frame__nav &,
  .page-opers &,
  .frame__info & {
    stroke: currentColor;
    color: currentColor;
    &.checked {
      stroke: $success-color;
      color: $success-color;
    }
  }


  .rowActionCell &,
  //.gwt-ScrollTable &, // Need to clarify (we don't need it everywere)
  .operPanel .searchForm &,
  .operPanel .btn:not(.btn--circle) &,
  .user-menu-item__icon &,
  .main-directories__sublink & {
    stroke: $text-color-base;
    color: $text-color-base;
    @include iconActionHover;
  }
    //.gwt-ScrollTable:hover &,
  //.operPanel .searchForm:hover &,
  //.operPanel .btn:hover &,
  //.user-menu-item:hover &, .user-menu-item:focus & {
  //  opacity: 1;
  //}

  .btn & {
    //height: 60%;
  }
  .btn--icon & {
    &.icon--plus {
      margin-top: -1px;
      margin-left: -1px;
    }
  }

  .btn--feedback &,
  .btn--chat & {
    fill: currentColor;
  }


  //add new widget icons
  &.icon--autoNumber,
  &.icon--multiline,
  &.icon--pickList,
  &.icon--number,
  //reporting chart icons
  &.icon--nochart,
  &.icon--verticalchart,
  &.icon--horizontalchart,
  &.icon--linechart,
  &.icon--areachart,
  &.icon--piechart,
  &.icon--donutchart,
  &.icon--semichart,
  &.icon--gaugechart,
  &.icon--funnelchart,
  &.icon--basicchart,
  &.icon--standartchart,
  &.icon--growthchart,
  &.icon--rankingchart {
    stroke:none;
  }

  &.icon--semichart {
    transform: scale(1.3);
  }
  &.icon--gaugechart {
    transform: scale(1.2);
  }
  &.icon--growthchart {
    transform: scale(.8);
  }
  &.icon--funnelchart {
    transform: scale(.9);
  }
}

