.dynamictable-header {
  @include table-cell-heading;
  padding: 0 5px 0;
  @include txtTruncate();
}

.dynamictable {
  width: auto !important;

  &--full-width {
    width: 100% !important;
  }

  &.competenciesTable {
    table-layout: fixed;
    border-spacing: 0;

    .form-group__content > & {
      margin-top: 0;
    }

    > tbody > tr > td {
      width: auto;
      vertical-align: top !important;

      + td {
        padding-left: $padding-x-base;
      }
    }
  }

  .localedWidget {
    td {
      vertical-align: top;

      &:first-child {
        &:has(input) {
          input {
            border-start-end-radius: 0;
            border-end-end-radius: 0;
          }

          & + td:last-child {
            > .btn {
              border-start-start-radius: 0;
              border-end-start-radius: 0;
            }
          }
        }

        &:has(textarea) {
          width: 316px;

          & + td:last-child {
            > .btn {
              margin-left: 4px;
            }
          }
        }
      }

      &:last-child {

      }
    }
  }

  .form-group__content & {
    margin-top: -4px;
  }

  .productstable-header {
    padding-left: 5px;
    text-transform: uppercase;
    font-size: 11px;
    color: #8D9BAB;
  }
  .combobox {
    line-height: 1;
  }


  td {
    border-radius: 0;
    input {
      padding: 0 5px;
    }
    .gwt-HTML, .gwt-Label {
      padding: 0 5px;
      color: $color-accent-2;
      line-height: 1.4;
    }
  }
  > tbody > tr {
    > td {
      background-color: white;

      > .gwt-CheckBox {
        line-height: 1.4;
      }
    }
    &:not(:first-child) > td {
      position: relative;
      //vertical-align: top !important; // that is good fot the next  // https://prnt.sc/pvsuwu but broke the alignment in the listing > edit form (.add-form) //https://prnt.sc/rxbo0q
      background-color: white;

      &.right-align-Cell {
        > .gwt-Label {
          display: inline-flex; //https://prnt.sc/rep94r
          align-items: center;
          justify-content: flex-end;
          height: $input-height;
          > * {
            vertical-align: middle !important;
          }
        }
      }

      #gwt-debug-Add_multi_task_assigneesEstimatedTime { //http://prntscr.com/of5xom
        width: 180px;
      }
    }
    &:first-child > td {
      background: none !important;
      border: none !important;
    }
  }

  //https://prnt.sc/sj1jdy
  .textAreaPanel {
    //margin-top: -20px;
    .counterGreen .counterLabel {
      position: absolute;
      width: auto;
      top: -5px;
      right: 5px;
      padding: 0 2px;
      font-size: 8px;
      //bottom: -10px;
      background-color: #fff;
    }
    .gwt-TextArea {
      font-size: .9em;
    }
  }
  &__actions {
    width: $button-height;

    .btn--icon {
      @include table-actions-svg;
    }
  }


  .gwt-CheckBox label,
  .gwt-RadioButton label,
  .control__indicator {
    vertical-align: baseline;
  }

  .input-field {
    margin-top: 0;
    position: relative;
  }

  td:not(.right-align-Cell) input:not([type="checkbox"]):not([type="radio"]),
  .simpleGwt-ComboBox,
  select {
    width: 100% !important;
    text-align: left !important;
  }
  .gwt-RadioButton {
    margin: 0 5px;
  }
  td .gwt-RadioButton {
    display: block;
    width: 17px;
    height: 17px;
    margin: 0 auto 0;
  }
  .cellBasedWidget-mod {
    @extend %form-control-style;
    min-height: $input-height;

    td {
      min-height: auto;
      height: auto;
      line-height: 13px;
      padding: 3px 10px;
    }
  }


  .input-field textarea,
  .gwt-TextArea {
    //position: absolute; //https://prnt.sc/pve6zd
    height: $button-height;
    width: 100% !important;
    font-size: 12PX;
    line-height: 1.4;
    max-height: 100px;
    transition: 0.1s all ease-out 0s;

    &:focus {
      z-index: 9;
      height: ($button-height * 1.5);
    }
  }
  .textAreaPanel {
    //.counterGreen
    .gwt-Label {
      margin-top: -20px; //https://prnt.sc/pve91k
      text-align: right;
      font-style: italic;
    }
  }
  .gwt-CheckBox {
    margin: 0 5px;
    white-space: nowrap; //http://prntscr.com/of60ql
  }
  .select2-container {
    border: none;
  }
  .select2-selection {
    border: none !important;
  }
  textarea {
    display: block;
    line-height: 1.4;
    padding-left: 5px;
    padding-right: 5px;
  }
  .gwt-TextBox,
  input[type='text'] {
    min-width: 50px;
  }

  .uploadLinkStyle {
    display: block !important;
    padding-left: 5px;
    line-height: 1.4;
  }

  table[title="DISCOUNT_AMT"] td {
    vertical-align: middle !important;
  }

} //End .dynamictable
.dynamictable:not(.RelatedTo-selection) {
  > tbody > tr > td,
  > tbody > tr > td > table > tbody > tr > td {
    > div {
      @include txtTruncate();
    }
  }

  .dynamictable__actions {
    > tbody > tr > td {
      padding-left: 0 !important;
      padding-right: 0;
    }
  }
}


tbody tr:not(:first-child) > td:first-child .dynamictable > tbody > tr:not(:first-child) > td:last-child {
  border-top-right-radius: 5px;
  border-bottom-right-radius: 5px;
}


.RelatedTo-selection { //https://prnt.sc/rq1ghy
  &__wrapper {
    border: 1px solid $control-border-color;
    > tbody > tr {
      + tr {
        > td {
          padding-top: 3px;
          padding-bottom: 3px;
        }
      }
      &:nth-child(even) {
        background-color: $color-base-contrast;
      }
    }
  }
  > tbody > tr > td {
    &:not(:last-child) {
      padding: 0 $control-padding-x;
    }
    &:last-child {
      svg {
        width: 15px;
        height: 15px;
        @include iconActionHover;
      }
    }
  }
}

