@mixin tabIndicator($color:$text-color-base) {
  position: relative;
  &:after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 50%;
    right: 50%;
    height: 2px;
    transition: left .25s ease, right .25s ease;
  }
  &.active {
    &:after {
      left: 0;
      right: 0;
      background-color: $color;
    }
  }
}
.tabs--indicator .tab a {
  @include tabIndicator($success-color) //message-center full chat
}

.tabs {
  position: relative;
  margin: 0 auto;

  &:not(.step-tabs) {
    display: flex;
    width: 100%;

    a {
      color: $tabs-text-color;
    }
  }

  &.step-tabs {
    display: inline-flex;
    $dashLineSize: 50px;

    .tab {
      position: relative;
        padding: 0 $dashLineSize / 2;
      + .tab {

        &:before {
          content: '';
          position: absolute;
          top: 50%;
          left: -$dashLineSize / 2;

          display: inline-block;
          width: $dashLineSize;
          height: 1px;
          background: $text-muted;
          opacity: .8;
        }
      }

      .btn {
        color: $text-muted;
        .badge {
          background-color: $text-muted;
        }
        &.active {
          color: $link-color;

          .badge {
            background-color: $link-color;
          }
        }
        &.passed {
          color: #000;

          .badge {
            background-color: #000;
          }
        }

        .badge {
          + span {
            margin-left: 5px;
          }
        }
      }
    }
  }
}

.tab {
  -webkit-box-flex: 1;
  -webkit-flex-grow: 1;
  -ms-flex-positive: 1;
  flex-grow: 1;
  text-align: center;
  padding: 0;
  margin: 0;
  text-overflow: ellipsis;

  a {
    text-overflow: ellipsis;
    transition: color .28s ease;

    &:not(.btn) {
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100%;
    }
  }

  &.disabled a {
    color: lighten($tabs-text-color, 20%);
    cursor: default;
  }

  .tabs2 > & {
    flex-grow: 0;

    > a {
      @include button-style();

      &.active {
        @extend .btn--darkgrey;
      }
    }
  }

  .tabs--high > & {
    flex-grow: 0;
    > a {
      border-top: 5px solid transparent;
      width: 100%;
      display: block;
      padding: rem(20px) rem(15px);
      transition: border-top-color 0.3s;
      position: relative;

      &:hover {
        border-top-color: #cfd6dc;
      }

        &.active {
          border-top-color: #cfd6dc;
        }

      &:before {
        content: '';
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-color: $gray-light;
        transition: opacity 0.3s;
        opacity: 0;
        z-index: -1;
      }

      &.active:before {
        opacity: 1;
      }
    }
  }
}
