/* Custom form noteWidget */
.noteWidget {
  max-width: 100%;
  table {
    table-layout: fixed;
    width: 100%;
  }
  .noteTextArea {
    width: 100%;
  }
  .gwt-RadioButton {
    margin-right: 15px;
  }
  .textAreaCounter {
    max-width: 200px;
    width: auto !important;
  }
  .notesPanel {
    margin-top: 20px;
    padding-right: 30px;
  }
  &__buttons {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    margin-top: 10px;
    margin-bottom: 10px;

    > div {
      &:first-child > *:not(:last-child) {
        margin-right: 15px;
      }

      &:last-child {
        margin-left: auto;

        .four-column & {
          margin-left: 0;
        }
      }
    }
    .four-column & {
      align-items: flex-start;
      padding-right: 0;
      flex-direction: column;
    }
  }
  .single-column &, .single-item & {
    max-width: 50%;
  }
}
.notesPanel {}
.noteTable {
  .notesContent {
    color: lighten($text-color-base, 15%);
  }
}
.notesFooter {
  font-weight: 500;
  font-size: .8em;
  margin: 3px 0 20px 0;
  display: flex;
  > * + * {
    margin-left: 10px;
  }
  .noteDate + .noteRemove {
    margin-left: 15px;
  }
  .noteRemove {
    text-transform: uppercase;
  }
}


