/* < WYSIWYG Editor > */
.code {
  .note-editor {
    background-color: transparent;
    border: none;
    .note-toolbar {
      z-index: 98 !important;
      background-color: transparent;
      padding: 0;
    }
    .note-editable {
      margin: 10px 0 0;
      box-shadow: none;
      border-radius: $radius-base;
      border: 1px solid $control-border-color;
    }
    .btn {
      height: 36px;
      line-height: 2.92307rem;
      background-color: transparent; //hidden border fix https://i.imgur.com/Es61FTO.png
      &:hover, &:active, &.active {
        background-color: $color-base-0 !important;
      }
    }
  }
  .note-toolbar {
    > .btn-group {
      margin: 0 4px 0 0;
      box-shadow: none;
      border: 1px solid $color-base-0-contrast;
      border-radius: $radius-base;

      .btn-group {
        margin: 0; //https://i.imgur.com/NXkLJrj.png
      }

      &:empty {
        margin: 0;
        border: none;
      }
      > .btn:first-child,
      > .btn-group:first-child .btn {
        border-top-left-radius: $radius-base !important;
        border-bottom-left-radius: $radius-base !important;
      }
      > .btn:last-child,
      > .btn-group:last-child .btn {
        border-top-right-radius: $radius-base !important;
        border-bottom-right-radius: $radius-base !important;
      }
    }
  }
}
/* </ WYSIWYG Editor > */

