:root .grid-stack-item > .ui-resizable-handle {
    filter: none;
}

.grid-stack {
    position: relative;
    body:not(.fitted-content) & {
        margin-left: -10px; // compensate the .grid-stack-item-content left/right 10px position used for widgets
        margin-right: -10px;
    }

    &.grid-stack-rtl {
        direction: ltr;
        > .grid-stack-item {
            direction: rtl;
        }
    }
    .grid-stack-placeholder > .placeholder-content {
        border: 1px dashed #d3d3d3;
        margin: 0;
        position: absolute;
        top: 0;
        left: 10px;
        right: 10px;
        bottom: 0;
        width: auto;
        z-index: 0 !important;
        text-align: center;
    }
    &.grid-stack-animate {
        -webkit-transition: left .3s, top .3s, height .3s, width .3s;
        -moz-transition: left .3s, top .3s, height .3s, width .3s;
        -ms-transition: left .3s, top .3s, height .3s, width .3s;
        -o-transition: left .3s, top .3s, height .3s, width .3s;
        transition: left 0.3s, top 0.3s, height 0.3s, width 0.3s;
        .grid-stack-item {
            -webkit-transition: left .3s, top .3s, height .3s, width .3s;
            -moz-transition: left .3s, top .3s, height .3s, width .3s;
            -ms-transition: left .3s, top .3s, height .3s, width .3s;
            -o-transition: left .3s, top .3s, height .3s, width .3s;
            transition: left 0.3s, top 0.3s, height 0.3s, width 0.3s;
            &.grid-stack-placeholder, &.ui-draggable-dragging, &.ui-resizable-resizing {
                -webkit-transition: left 0s, top 0s, height 0s, width 0s;
                -moz-transition: left 0s, top 0s, height 0s, width 0s;
                -ms-transition: left 0s, top 0s, height 0s, width 0s;
                -o-transition: left 0s, top 0s, height 0s, width 0s;
                transition: left 0s, top 0s, height 0s, width 0s;
            }
        }
    }
    &.grid-stack-one-column-mode {
        height: auto !important;
    }

    .custom-form-grid & {
        margin-left: $padding-x-base - rem(5px);
        margin-right: $padding-x-base - rem(5px);
    }
}

.grid-stack-item {
    min-width: 8.3333333333%;
    position: absolute;
    padding: 0;

    &.grid-stack__heading {
        .dashboard__content > & {
            position: static;
        }
    }

    .custom-form-grid & {
        height: $dragTileHeight !important;
        min-height: $dragTileHeight !important;
    }

    &-content {
        position: absolute;
        z-index: 0 !important;
        top: 0;
        bottom: 0;
        left: 10px;
        right: 10px;
        margin: 0;

        .dashboard__container & {
            @extend %panel-style;
            //overflow-x: hidden;
            //overflow-y: auto;
            overflow: hidden !important; //prevent scroll heading
            width: auto;
            height: 100%;
        }

        .custom-form-grid & {
            left: 5px;
            right: 5px;
        }

        > .gwt-wrapper {
            height: 100%;
        }

        &.ui-draggable-handle{
            border:1px solid rgba(236, 239, 243, 0.4588235294117647);
        }

        .custom-form-grid & {
            //@include drag-tile-style;
            //top: -1px;
            //bottom: -1px;
        }
    }
    .grid-stack-one-column-mode & {
        position: relative !important;
        width: auto !important;
        left: 0 !important;
        top: auto !important;
        margin-bottom: 20px;
        max-width: none !important;
        > .ui-resizable-handle {
            display: none;
        }
    }

    .ui-resizable-handle {
        position: absolute;
        font-size: .1px;
        display: block;
        -ms-touch-action: none;
        touch-action: none;
    }
    &.ui-resizable-autohide > .ui-resizable-handle, &.ui-resizable-disabled > .ui-resizable-handle {
        display: none;
    }
    &.ui-draggable-dragging, &.ui-resizable-resizing {
        z-index: 100;
    }
    &.ui-draggable-dragging > .grid-stack-item-content, &.ui-resizable-resizing > .grid-stack-item-content {
        box-shadow: 1px 4px 6px rgba(0, 0, 0, 0.2);
        opacity: 0.8;
    }
    > {
        .ui-resizable-se, .ui-resizable-sw {
            background-image: url(data:image/svg+xml;base64,);
            background-repeat: no-repeat;
            background-position: center;
            -webkit-transform: rotate(45deg);
            -moz-transform: rotate(45deg);
            -ms-transform: rotate(45deg);
            -o-transform: rotate(45deg);
            transform: rotate(45deg);
        }
        .ui-resizable-se {
            -webkit-transform: rotate(-45deg);
            -moz-transform: rotate(-45deg);
            -ms-transform: rotate(-45deg);
            -o-transform: rotate(-45deg);
            transform: rotate(-45deg);
        }
        .ui-resizable-nw {
            cursor: nw-resize;
            width: 20px;
            height: 20px;
            left: 10px;
            top: 0;
        }
        .ui-resizable-n {
            cursor: n-resize;
            height: 10px;
            top: 0;
            left: 25px;
            right: 25px;
        }
        .ui-resizable-ne {
            cursor: ne-resize;
            width: 20px;
            height: 20px;
            right: 10px;
            top: 0;
        }
        .ui-resizable-e {
            cursor: e-resize;
            width: 10px;
            right: 10px;
            top: 15px;
            bottom: 15px;
        }
        .ui-resizable-se {
            cursor: se-resize;
            width: 20px;
            height: 20px;
            right: 10px;
            bottom: 0;
        }
        .ui-resizable-s {
            cursor: s-resize;
            height: 10px;
            left: 25px;
            bottom: 0;
            right: 25px;
        }
        .ui-resizable-sw {
            cursor: sw-resize;
            width: 20px;
            height: 20px;
            left: 10px;
            bottom: 0;
        }
        .ui-resizable-w {
            cursor: w-resize;
            width: 10px;
            left: 10px;
            top: 15px;
            bottom: 15px;
        }
    }
    &.ui-draggable-dragging > .ui-resizable-handle {
        display: none !important;
    }
