@import "gulp-scss/components/mixins/border-radius";

// LINKS
@mixin link($color:$link-color) {
  color: $color;
  text-decoration: none;
  cursor: pointer;
  // Gets rid of tap active state
  -webkit-tap-highlight-color: transparent;

  &:hover, &:focus {
    //color: darken($color, 15%); //!important; //important for .dropdown-content > li.active a:hover custom <a> el
    color: darken($color, 10%);
  }
}

@mixin closeHover($scale: 1.15) {
  &:hover {
    transform: scale(#{$scale});
    transition: transform .15s ease;
  }
}

// FORM CONTROLS
@mixin form-control-readonly {
  color: $input-disabled-color !important;
  background-color: $input-disabled-bg !important;
  cursor: default;
}

@mixin form-control-disabled {
  @include form-control-readonly;
  user-select: none;
}

@mixin form-control() { //
  //padding: $button-padding-y $control-padding-x;
  //border-radius: $control-border-radius;
  //font-size: $control-font-size;
  //color: $color-form-control;
  //text-overflow: ellipsis;
}

@mixin form-control-size($hightVers: height, $lineHeight: true) {
  box-sizing: border-box;
  #{$hightVers}: $input-height;
  @if $lineHeight {
    line-height: $input-btn-line-height;
  }
}

@mixin form-control-style($borderColor: $control-border-color, $paddingX: $control-padding-x, $color: true) {
  border: $control-border-width solid $borderColor;
  padding-left: $paddingX;
  padding-right: $paddingX;
  border-radius: $control-border-radius;
  text-decoration: none;
  letter-spacing: .5px;
  font-style: normal;
  font-size: $control-font-size;
  //transition: box-shadow .2s ease-out;
  outline: none;
  @if $color {
    color: $color-form-control; // for link buttons <a class="
    &:hover {
      color: $control-text-color;
    }
  }
}

@mixin common-input-mixin() {
  @include form-control-style();
  display: block;
  width: 100%;
  padding: $button-padding-y $control-padding-x;
  background-color: #fff;
  background-image: none;
  background-clip: padding-box;
}

@mixin text-input-mixin() {
  @include form-control-size; //height, line-height
  @include common-input-mixin();
  white-space: nowrap;
}

