// BUTTONS
@mixin button-style($color: true) {
  @extend %form-control-size;
  @include form-control-style($borderColor: transparent, $paddingX: $button-padding-x, $color: $color);
  //border-width: 1px;
  transition: background-color .1s ease;

  .group-box__item-content & {
    height: $control-height-noBorder;
    line-height: $input-btn-line-height - $control-border-width * 2;
  }
}

@mixin button-style-sm() {
  @extend %form-control-size-small; //height, line-height, nowrap
  @include form-control-style($borderColor: transparent, $paddingX: ($button-padding-x * .4), $color: false);
}

@mixin button-style-md() {
  //%extend %form-control-size-medium; //height, line-height, nowrap
  height: $button-height-medium;
  line-height: $button-line-height-medium;
  font-size: $button-font-size-medium;
  @include form-control-style($borderColor: transparent, $paddingX: $button-padding-x, $color: false);
}

@mixin button-style-lg() { //ToDo check it
  @extend %form-control-size-large; //height, line-height, nowrap
  @include form-control-style($borderColor: transparent, $paddingX: $button-padding-x, $color: false);
}

