@mixin dropdown-content-list-item-style {
  text-align: left;

  &:after {
    display: block;
    content: '';
    position: absolute;
    bottom: 0;
    left: 16px;
    right: 16px;
    height: 1px;
    background: #e6eaee;
    opacity: .5;
    transition: opacity .3s ease-in;

    .form-control & {
      left: 0;
      right: 0;
    }
  }

  &.active.selected {
    > a {
      //color: #fff; make text invisible in gwt-listbox <select>
    }
  }

  &:hover, &:focus {
    &:after {
      opacity: 1;
    }
  }

  &:last-child:after {
    background: transparent;
  }
}

