//PANELS
@mixin panel-list($radius: $radius-big, $background: #fff) {
  border-radius: $radius;
  background-color: $background;
  padding-left: $gridGutterSingle;
  padding-right: $gridGutterSingle;

  > * {
    margin-left: -$gridGutterSingle;
    margin-right: -$gridGutterSingle;
    padding: $gridGutterSingle;
  }

  > :first-child {
    @include border-top-radius($radius)
  }
  > :last-child {
    @include border-bottom-radius($radius)
  }
}

@mixin panelStyle($radius: $radius-big, $padding-x: $panel-padding, $background: #fff, $bdcolor: $panelBorderColor, $bordered: false, $body: false, $heading: false, $footer: false) {
  border-radius: $radius;
  background-color: $background;

  @if $bordered {
    border: 1px solid $bdcolor;
    .panel__heading:where(:not(:last-child)) {
      border-bottom: 1px solid $bdcolor;
    }
  }

  @if $heading {
    &__heading {
      padding-left: $padding-x !important;
      padding-right: $padding-x !important;
      @include border-top-radius($radius)
    }
  }
  @if $body {
    &__body {
      padding-left: $padding-x !important;
      padding-right: $padding-x !important;
      padding-bottom: $padding-x;

      &:only-child,
      &:first-child:where(:not(:last-child)),
      & + & {
        padding-top: ($padding-x);
      }

      &:last-child {
        @include border-bottom-radius($radius)
      }
    }
    &__heading + &__body {
      padding-top: ($padding-x * .8);
    }
  }
  @if $footer {
    &__footer {
      @include border-bottom-radius($radius)
    }
  }
}

//COLLAPSIBLE
@mixin collapsible-arrow() {
  &:after {
    position: absolute;
    top: 50%;
    margin-top: -.5em;
    font-weight: bold;
    font-size: 27px;
    font-size: rem(27px);
    line-height: 1;
    @extend .ficon--;
    @extend .ficon--keyboard-arrow-down:before;
  }
  //li.active &,
  &.active {
    &:after {
      @extend .ficon--keyboard-arrow-up:before;
    }
  }
}


@mixin close-button() {
