@mixin css-close-button($size) {
  position: relative;
  font-size: 0;
  line-height: 0;
  &:before, &:after {
    content: '';
    position: absolute;
    height: $size;
    width: 1px;
    left: 50%;
    top: 50%;
    margin-top: -($size / 2);
    opacity: .5;
    background-color: $text-color-base;
  }
  &:before {
    transform: rotate(45deg);
  }
  &:after {
    transform: rotate(-45deg);
  }
  &:hover {
    &:before, &:after {
      opacity: 1;
    }
  }
}

