@mixin historyPoint {
  content: '';
  position: absolute;
  border-radius: 50%;
  width: rem(9px);
  height: rem(9px);
  border: rem(2px) solid $color-base-contrast;
  background-color: $gray-darkest;
}

@mixin rhomb($el:before, $pos:left, $size:6px, $color:#a7b2bc) {
  &:#{$el} {
    content: '';
    position: absolute;
    #{$pos}: -($size / 2);
    width: $size;
    height: $size;
    transform: rotate(-45deg);
    background: $color;


    @if $pos == left or $pos == right {
      top: 50%;
      margin-top: -($size / 2);
      @content;
    }

    @if $pos == top or $pos == bottom {
      left: 50%;
      margin-left: -($size / 2);
      @content;
    }
  }
}

@mixin before-after($top: false, $bottom: false, $left: false, $right: false, $content:'') {
  &:before, &:after {
    content: $content;
    position: absolute;
    @content;
    @if $top {
      top: $top;
    }
    @if $bottom {
      bottom: $bottom;
    }
    @if $left {
      left: $left;
    }
    @if $right {
      right: $right;
    }
  }
}

@mixin before($top: false, $bottom: false, $left: false, $right: false, $content:'') {
