//Layout mixins
@mixin triple-growCenter($selector, $display: flex, $space-x: $gridGutterSingle, $prefix: 'icon', $sufix: 'txt', $postfix: 'act') {
  #{$selector} {
    display: $display;
    justify-content: stretch;
    align-items: center;

    &__#{$sufix} {
      flex: 1 auto;
      margin-left: $space-x;
      margin-right: $space-x;
    }

    &__#{$prefix}, &__#{$postfix} {
      flex: 0 auto;
      display: grid;
      place-content: center;
    }

    &__#{$prefix} {
      img {
        max-width: 100%;
      }
    }

    &__#{$postfix} {
      i {
        display: flex;
        cursor: pointer;

        &:hover {
          @include closeHover();
        }
      }
    }
  }
}

