//EXTENDS
%fixed-content {
  position: fixed !important;
  transition: left $leftBar-transition;

  html:not([dir="rtl"]) & {
    left: $frameModulesSize !important;
    right: 0 !important;

    .fitted-content & {
      padding-right: 0 !important;
    }
  }

  html[dir="rtl"] & {
    left: 0 !important;
    padding-left: $padding-x-base !important;
  }

  html[dir="rtl"] & {
    right: $frameModulesSize !important;
  }

  .left-menu-open & {
    html:not([dir="rtl"]) & {
      left: ($frameNavSize + $frameModulesSizeOpen) !important;
    }
    html[dir="rtl"] & {
      right: ($frameNavSize + $frameModulesSizeOpen) !important;
    }
  }
}


