.dashboard__container {

  position: relative;
  .cp_grid {
    position: absolute;
    margin-left: -10px;
    margin-right: -10px;
    overflow: hidden;
    display: flex;
    flex-wrap: wrap;
    //padding: 0 10px;
    padding: 0;
    div {
      opacity:0;
      transform:scale(0);
      transition: all 0.3s ease-out 0s;
      width: 8.333333333333333%;
      padding: 0 10px;
      margin-bottom: 20px;
      &:after {
        content: "";
        display: block;
        height: 80px;
        background: #f6f7f9;
        border-radius: 5px;
        transition: all 0.3s ease-out 0s;
      }
      &.active:after{
        background-color: #bdc4cc;
      }
    }
  }

  &--edit{
    .cp_grid div{

      opacity: 1;
      transform:scale(1);
    }
  }

  .grid-stack-item{
    &:not(.ui-draggable-disabled){
      cursor: move !important;
    }
    .ui-draggable-handle {
      //border: 1px solid white;
      box-shadow: 0 10px 20px rgba(0,0,0,0.00), 0 6px 6px rgba(0,0,0,0.00);
      transition: box-shadow 0.2s ease-out 0s;
    }

    //on edit
    &:not(.ui-resizable-disabled) .ui-draggable-handle {
      box-shadow: 0 10px 20px rgba(0,0,0,0.05), 0 6px 6px rgba(0,0,0,0.08);
      //box-shadow: rgba(0, 0, 0, 0.05) 0px 10px 20px -15px, rgba(0, 0, 0, 0.08) 0px 19px 13px -10px;
    }
    //on edit hover
    &:not(.ui-resizable-autohide) .ui-draggable-handle {
      border: 1px dashed #848587;
    }

    &:not(.ui-resizable-disabled) .ui-resizable-handle{
      display: flex !important;
    }
    &:not(.ui-resizable-autohide) .ui-resizable-handle:after {
      opacity: 1;
      transform: scale(1);
    }
    &>.ui-resizable-handle{
      z-index: 1 !important;
      justify-content: center;
      align-items: center;
      overflow: visible;
      background: none;
      &:after {
        opacity: 0;
        transform: scale(0);
        content: "";
        display: block;
        flex-shrink: 0;
        width: 15px;
        height: 15px;
        background: white;
        border: 1px solid $gray-new-light;
        box-shadow: 0px 0px 10px 0px $gray-new-light;
        transition: all 0.1s ease-out 0s;
      }
      &.ui-resizable-e:after {
        margin-right: -8px;
      }
      &.ui-resizable-w:after {
        margin-left: -8px;
      }
      &.ui-resizable-s:after {
        margin-bottom: -8px;
      }
      &.ui-resizable-w:after {
        margin-left: -8px;
      }
      &.ui-resizable-s:after {
        margin-bottom: -8px;
      }
      &.ui-resizable-sw, &.ui-resizable-se {
        transform: rotate(0deg) !important;
        background: none;
      }
      &.ui-resizable-sw:after {
        margin-bottom: -15px;
        margin-left: -18px;
      }
      &.ui-resizable-se:after {
        margin-bottom: -15px;
        margin-right: -18px;
      }
    }
    .grid-stack-item-header{

    }
  }
}

.dashboard__header {
  height: 0;
  //transition:height 0.3s ease-out 0s;
  .panel-box__item{
    max-width: 0;
    opacity: 0;
    transition:all 0.4s ease-out 0.0s;
  }
  &.fixed-content {
    z-index:2;
  }
  .panel-box--right {
    padding-right: $frameContentPadding; //https://prnt.sc/r0mxo7
  }
}

.dashboard__container{
  overflow: hidden;
  .cp_grid{
  }
  &--edit{
    .dashboard__header{
      height: rem(60px);
      .panel-box__item{
        max-width: 250px;
        opacity:1;
        transition-delay:inherit;
      }
    }
  }
}
.dashboard__content{
  padding: 0 !important;
  margin-top:0px;
  //transition:margin-top 0.3s ease-out 0s;
  &--edit{
    margin-top:rem(60px);
    min-height: 1600px;

  }
}



/*widget close button*/
.widget-delete{
  width: $widget-heading-height;
  height: $widget-heading-height;
  line-height: $widget-heading-height;
  position: absolute;
  z-index:1;
  top:1px;
  right: 11px;
  font-size: 1.4rem;
  color: #8d9ba8;
  background-color: white;
  text-align: center;
  cursor: pointer;
  border-left: 1px solid $gray-new-light;
  transition:background 0.2s ease-out 0s;
  border-top-right-radius: 5px;
}
.dashboard__content--edit .widget-row-head{
  html:not([dir="rtl"]) & {
    margin-right: 60px;
    padding-right: 20px;

    @media screen and (max-width: 1366px) { //https://prnt.sc/s4qduh
      margin-right: 50px;
      padding-right: 15px;
    }
  }
}
.ui-resizable-resizing, .ui-draggable-dragging{
  .widget-delete{
    opacity: 0.5;
  }
}

.widget-delete:hover{
  background-color: #f6f7f9;
  color: #8d9ba8;
}

