.gwt-PopupPanel {
  &:not(.calendarPopup) {

  }
  padding: $gwtPopupPanel-padding;
  border-radius: 5px;
  border: none;

  &.calendarPopup {
    border: 1px solid $gray-border;
    box-shadow: $popupBoxShadow;
  }


  .close-x {
    position: absolute;
    z-index: 11; // to be over the popupContent
    top: 8px;
    right: 1.25rem;
    cursor: pointer;
  }

  .accept, .cancel {
    width: 40px;
    height: 40px;
    speak: none;
    font-style: normal;
    font-weight: normal;
    font-variant: normal;
    text-transform: none;
    font-family: 'icomoon';
    line-height: 40px;
    text-align: center;
    transition: opacity 0.2s;
    opacity: 1;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  .accept:hover, .cancel:hover {
    opacity: 0.7;
  }

  .accept {
    border-radius: 5px 0 0 5px;
    background-color: #85CA40;
    font-size: 15px;
    color: white;

    &:before {
      content: "\e902";
    }
  }

  .cancel {
    &:before {
      content: "\e91b";
    }
  }

  .popupContent {
    border: none !important;
  }

  .content td {
    display: block;
  }

  .gwt-TextArea {
    width: 100%;
  }

  .accept-cancel-group {
    display: flex;
    justify-content: flex-end;
  }
}
