.modal.modal--kpi-upload {
  //width: 44%;
}

.modal--kpi-upload .modal-wrapper {
  //height: 80%; //https://prnt.sc/pvtgw4
}

.modal--kpi-upload .modal-content {
  padding: 0;
  height: 100%;
}

.kpi-upload {
  //overflow: hidden;
  display: flex;
  background-color: white;
  height: 100%; // need to provide scroll for child list
  min-width: 642px;
  min-height: 486px;
}

.kpi-upload__main-content {
  flex: 1 1 auto;
  display: flex;
  flex-flow: column;
}

.kpi-upload__side-content {
  border-left: 1px solid $color-base-0;
  flex: 0 0 20.77rem;
  overflow: auto; // in order to provide overfow: ellipsis to the .kpi-upload__upload-file-name https://prnt.sc/qagbb1
  display: flex;
  flex-flow: column;
  /* $gray-middle */
}

.kpi-upload__section {
  border-top: 1px solid $color-base-0;
  /* $gray-middle */
  padding: 1.53rem 0 1.92rem;
}

.kpi-upload__tabs {
  border-bottom: 1px solid $color-base-0;
  /* $gray-middle */
  display: flex;
  flex-shrink: 0;
}


.kpi-upload__tabs-item {
  min-height: 4.61rem;
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  flex-grow: 1;
  background-color: #F9FAFB;
  position: relative;
  flex-basis: 0;
}

.kpi-upload__tabs-item:not(.kpi-upload__tabs-item--active):not(.kpi-upload__tabs-item--locked):hover {
  background-color: #efefef;
}

.kpi-upload__tabs-item--active {
  background-color: white;
  cursor: default;
}

.kpi-upload__tabs-item--locked {
  opacity: 0.5;
  cursor: default;
}

.kpi-upload__tabs-item--locked:before {
  content: "\e975";
  font-family: 'icomoon' !important;
  speak: none;
  font-style: normal;
  font-weight: normal;
  font-variant: normal;
  text-transform: none;
  line-height: 1;
  -webkit-font-smoothing: antialiased;
  position: absolute;
  top: 10px;
  right: 10px;

}

.kpi-upload__tabs-item:not(:first-child) {
  border-left: 1px solid $color-base-0;
  /* $gray-middle */
}

.kpi-upload__tabs-item .ficon--folder-bold {
  font-size: 1.38rem;
  color: #8d9ba8;
  /* $gray-dark */
  padding-bottom: 0.38rem;
}

.kpi-upload__tabs-item .ficon--office365 { //Replaced to image > see below
  font-size: 2.46rem;
  color: #e54b19;
}

.kpi-upload__tabs-item-google-icon {
  width: 27px;
  height: 23px;
  background-image: url(data:image/svg+xml;base64,);
  background-size: contain;
  background-repeat: no-repeat;
}

.kpi-upload__tabs-item-drive-365 {
  width: 27px;
  height: 23px;
  background-image: url(data:image/svg+xml;base64,);
  background-size: contain;
  background-repeat: no-repeat;
}

.kpi-upload__content-wrapper {
  overflow: hidden;
  flex: 1 1 auto;
  padding: 0 $panel-padding;

  .form-group.mb-0 {
    .form-group__content {
      display: flex;
      justify-content: space-between;

      .btn--primary {
        min-width: 115px;
      }
    }
  }
}

.kpi-upload__dropzone {
  position: relative;
  display: flex;
  flex-direction: column;
  flex-grow: 1;

  .dropzone {
    flex-grow: 1;

  }

  .dropzone input[type="file"] { //dropzone.js overrides
    width: 100% !important;
    height: 100% !important;
  }
}

.kpi-upload__description {
  flex: 0 0 80px;
  display: flex;
  flex-direction: column;
  justify-content: center;

  input {
    width: 100% !important;
  }
}

.kpi-upload__upload-icon {
  margin-top: 3.07rem;
  margin-bottom: 3.07rem;

  i {
    font-size: 10rem;
    color: #DEE0E2;
  }
}

.kpi-upload__upload-file {
  display: flex;
  border-bottom: 1px solid $color-base-0;
  /* $gray-middle */
  //background-color: #f6f7f9;
  /*  $gray-light */

  + .kpi-upload__upload-file {
    margin-top: 1px;
  }

  > * {
    padding-top: 2px;
    padding-bottom: 2px;
  }

  &:hover {
    .kpi-upload__upload-file-progress i {
      background-color: darken(#85CA40, 10%);
    }
  }

  &--in-process,
  &--selected,
  &--ready {
    .kpi-upload__content-wrapper:hover {
      cursor: pointer;
      text-decoration: underline;
    }
  }

  &--in-process {
    background-color: $gray-light;
    border-bottom-color: #fff;
  }

  &--selected {
    background-color: $gray;
  }

  &--ready {
    background-color: white;
  }
}

.kpi-upload__upload-file-name {
  @include txtTruncate();
}


.kpi-upload__upload-file
.kpi-upload__upload-file > .kpi-upload__content-wrapper {
  padding-top: 0.8rem;
  padding-bottom: 0.8rem;
  padding-right: 1.5rem;
  overflow: hidden;
}

.kpi-upload__upload-file-row {
  @include txtTruncate();
}

.kpi-upload__upload-file-delete {
  flex: 0 0 3.07rem;
  display: flex;
  border-left: 1px solid $color-base-0;

  .kpi-upload__upload-file--in-process & {
    border-left-color: #fff;

    &:not(:hover) {
      i {
        color: $color-base-2;
      }
    }
  }

  /* $gray-middle */
  margin-left: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  //background-color: white;

  &:hover {
    background-color: $gray-middle;
  }

}

.kpi-upload__upload-file-delete i {
  font-size: 1.3rem;
}

.kpi-upload .dropzone-message {
  font-size: 1.23rem;
  color: #8d9ba8;
}

.kpi-upload .dropzone-submessage {
  color: #8d9ba8;
  /* $gray-dark */
  opacity: 0.65;
  margin-top: 3.07rem;
}

.kpi-upload__side-header {
  font-size: 1.23rem;
  display: flex;
  align-items: center;
  min-height: 4.61rem;
  border-bottom: 1px solid $color-base-0;
  box-sizing: content-box;
}

/* Rewrites */
/* -------- */

.kpi-upload .dropzone {
  align-items: center;
  border: none;
}

/*folder panel*/

.kpi-upload__folder-parent {
  padding: .8rem .3rem .8rem 2.3rem;
  border-bottom: 1px solid $color-base-0;
  cursor: pointer;

  &--selected {
    background-color: $gray;
  }
}

.kpi-upload__folder-parent:hover {
  background-color: rgba(246, 247, 249, 0.4);
}

.kpi-upload__folder-child .kpi-upload__upload-file:hover {
  background-color: rgba(246, 247, 249, 0.5);
  cursor: pointer;

}

.kpi-upload__folder-parent:before {
  display: inline-block;
  width: 20px;
  height: 20px;
  line-height: 20px;
  text-align: center;
  border-radius: 50%;
  font-size: 1.5rem;
  color: white;
  vertical-align: middle;
  margin-right: 15px;
  content: "+";
  background: #85CA40;
  box-shadow: 0px 3px 5px 0px rgba(133, 202, 62, 0.7);
  transition: background .1s ease-out 0s;
}

.kpi-upload__folder-parent:not(.collapsed):before {
  content: "-";
  background: #8D9BA8;
  box-shadow: 0px 3px 5px 0px rgba(141, 155, 168, 0.7);
}

.kpi-upload__folder-parent span {
  vertical-align: middle;
  line-height: 20px;
}

.kpi-upload__folders-wrap {
  overflow: auto;
  position: relative;
  flex-grow: 1;
}

.kpi-upload__checkbox-item {
  margin-bottom: .5rem;
}

.kpi-upload__checkbox-item label {
  cursor: pointer;
}

.kpi-upload__checkbox-item .gwt-CheckBox {
  padding-left: 2.5rem;
}

.kpi-upload__checkbox-item .gwt-CheckBox label:before {
  //border-color: #E8E8E8;
  border-color: lighten($checkbox-border-color, 10%);
}

.kpi-upload__checkbox-item .gwt-CheckBox label {
  padding-top: 0.15385rem;
}

.kpi-upload__list-header {
  margin: 1.8rem 2.3rem;
}

.kpi-upload__list .searchForm {
  //border: 1px solid #E1E5EC;
  //border-radius: 5px;
  //width: auto;
}

.kpi-upload__list .searchForm__btn {
  color: #8D9BA8;
}

.kpi-upload__list {
  flex-grow: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  position: relative;
  min-height: 0;
}

.kpi-upload__checkbox-list {
  flex-grow: 1;
  margin: 0rem 0.3rem 1.8rem 2.3rem;
  overflow: auto;

  .kpi-upload__checkbox-item {
    margin-left: 0 !important;
    padding-right: 2rem;
    width: 100%;
    @include txtTruncate();
  }
}

.kpi-upload__checkbox-list-empty {
  position: absolute;
  left: 0;
  right: 0;
  top: 40%;
  text-align: center;
  padding: 2rem;
}

.kpi-upload__list-more {
  line-height: 3.5rem;
  text-align: center;
  background: #F9FAFB;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.2s ease-out 0s;
}

.kpi-upload__list-more:hover {
  background-color: #f4f5f6;
}


.collapse {
  display: none
}

.collapse.in {
  display: block
}

.collapsing {
  position: relative;
  height: 0;
  overflow: hidden;
  -webkit-transition: height .35s ease;
  transition: height .35s ease
}

//
.kpi-upload__upload-files-list {
  overflow: auto;
}

.kpi-upload__upload-file-row {
  display: flex;
  align-items: center;
}

.kpi-upload__upload-file-progress {
  margin-right: 15px;
  width: 23px;
  flex-grow: 0;
  flex-shrink: 0;
}

@keyframes upload-success {
  0% {
    transform: scale(0);
  }
  50% {
    transform: scale(1);
  }
  75% {
    transform: scale(.8);
  }
  100% {
    transform: scale(1);
  }
}

.kpi-upload__upload-file-progress i {
  display: block;
  border-radius: 50%;
  width: 21px;
  height: 21px;
  line-height: 23px;
  text-align: center;
  background-color: #85CA40;
  color: white;
  transition: transform 0.2s ease-out 0s;
  animation: upload-success .5s;
}
.kpi-upload__folder-child .kpi-upload__folder {
  width: 100%;
}

.kpi-upload__folder-child .kpi-upload__folder {
  padding-left: 2rem;
}

.storage-informer {
  border: 1px solid $control-border-color;
  border-radius: $control-border-radius;
  padding: $control-padding-x;
  background-color: $color-base-contrast;

  .kpi-upload__dropzone & {
    margin-left: 2.3rem;
    margin-right: 2.3rem;
  }

  //.fs-2
  strong {
    font-weight: 500;
  }

  dl {
    margin: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;

    dt {
      flex-grow: 1;
    }

    dd {
      flex-grow: 0;
      flex-shrink: 0;
    }
  }

  .determinate {
    background-color: $link-color;
  }
}