/* New Ui for home page */

.reports-link-control {
  margin-bottom: 10px;
  display: flex;
  width: 100%;
}


.reports-link-control--bright .reports-link-control__input:hover, .reports-link-control--bright .reports-link-control__name:hover {
  background-color: white;
}

.reports-link-control > *:first-child {
  border-top-left-radius: 5px;
  border-bottom-left-radius: 5px;
}

.reports-link-control > *:last-child {
  border-top-right-radius: 5px;
  border-bottom-right-radius: 5px;
}

.reports-link-control > .figure-actions:last-child {
  display: flex;
  flex-direction: column;
  justify-content: center;
  background-color: #F7F8FA;
}

.reports-link-control__bage {
  position: relative;
  display: inline-block;
  color: white;
  z-index: 1;
  padding-right: 12px;
  padding-left: 12px;
  margin: 0 10px;
}

.reports-link-control__bage:first-child {
  margin-left: 0;
}

.reports-link-control__bage:last-child {
  margin-right: 0;
}

.reports-link-control__bage > i {
  font-size: 0.8rem;
}

.reports-link-control__bage:after {
  content: '';
  display: block;
  position: absolute;
  border-radius: 20px;
  left: 0;
  right: 0;
  top: -5px;
  bottom: -5px;
  background-color: $color-accent-2;
  z-index: -1;
}

.reports-link-control__bage--alert:after {
  background-color: #73CF19;
}

.reports-link-control__input {
  padding-left: 15px;
  padding-right: 12px;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.reports-link-control__input input {
  display: none;
}

.reports-link-control__input i {
  color: $button-color-darkgrey;
}

.reports-link-control__input input:checked + i {
  color: #00A8EA;
}

.reports-link-control__input:after {
  content: '';
  position: absolute;
  top: 5px;
  bottom: 5px;
  border-right: 1px solid $filter-border-color;
  right: 0;
}

.reports-link-control__name {
  padding-right: 55px;
  padding-left: 13px;
  position: relative;
  flex-grow: 1;
  @include txtTruncate();
}

.reports-link-control__name, .reports-link-control__input {
  background-color: #F7F8FA;
  transition: background-color 0.3s;
  cursor: pointer;
  padding-top: 15px;
  padding-bottom: 15px;
}

.reports-link-control__name:hover, .reports-link-control__input:hover {
  background-color: #ECEFF3;
}

.reports-link-control__name > i {
  position: absolute;
  right: 25px;
  top: 50%;
  margin-top: -0.7rem;
  font-weight: bold;
  color: #CED6DD;
  opacity: 0;
  font-size: 1.4rem;
  transition: all 0.3s;
}

.reports-link-control__name:hover > i {
  display: block;
  transform: translateX(5px);
  opacity: 1;
}


.tabs.tabs--inside-block .tab {
  flex-grow: 0;
}

.tabs--inside-block .tab a {
  padding: 20px;
  position: relative;
}

.tabs--inside-block .tab a:after {
  content: '';
  left: 50%;
  right: 50%;
  background-color: $color-accent-2;
  height: 1px;
  position: absolute;
  bottom: 0;
  transition: all 0.36s;
}

.tabs--inside-block .tab a.active:after {
  left: 0%;
  right: 0%;
}


//https://prnt.sc/rsqjmp
.table_rowManage {
  border-collapse: separate;
  border-spacing: 0 10px;

  > tbody {
    > tr {
      > * {
        height: 40px;
        padding: 0;
        position: relative;

        &:first-child {
          text-align: right;

          > * {
            margin-right: 15px;
          }
        }

        &:not(:first-child) {
          border-style: solid;
          border-color: $filter-border-color;
          border-top-width: 1px;
          border-bottom-width: 1px;
          border-right-width: 0;
          border-left-width: 0;

        }

        &:nth-child(2) {
          border-left-width: 1px;
          border-radius: 5px 0 0 5px;
        }

        &:last-child {
          border-right-width: 1px;
          border-radius: 0 5px 5px 0;
        }
      }

      > td {
        background-color: white;
      }

      > td + td:before {
        content: '';
        position: absolute;
        z-index: 1;
        width: 1px;
        left: 0;
        top: 5px;
        bottom: 5px;
        background: $filter-border-color;
      }

      &:not(:last-child) {
        .rowControl--add {
          visibility: hidden;
        }
      }

      .show_filter & {
      }

      .hide_filter & {
        &:not(:last-child) {
          .rowControl--add {
            visibility: visible;
          }
        }

        &:not(:nth-child(2)) {
          .rowControl--add {
            visibility: hidden;
          }
        }
      }
    }

    .form-control,
    .form-control .gwt-ListBox > input {
      border: none;
    }
  }

  > tfoot {
    th {
      padding-right: 0;
      padding-top: 15px;
      height: 3.07692rem;
    }
  }

  .customReport_tab_6__num {
    text-align: center;
    background: $color-base-contrast;
  }

  .filter_panel_flex {
    .filter_label {
      display: none;
    }
  }

  .simpleGwt-ComboBox {
    width: 100%;
  }

  .hide_filter & {
    position: relative;
    //margin-top: 40px; //hight of tr
    > tbody > tr:last-child {
      //position: absolute;
      //top: 0;
    }
  }
}

