.fullChat {
  height: calc(100% - 1px);
  margin-top: 1px;
  display: flex;

  > * {
    width: 100%;
    min-height: 1px;
  }

  &__list {
  }
  .tabs {
    height: $button-height;
  }

  &__chat {
    flex: 0 0 50%;
    max-width: 50%;
    padding: $gridGutterSingle $grid-gutter-width 0;
  }
  &__info {
    padding-top: $gridGutterSingle;
  }

  &__list,
  &__info {
    flex: 0 0 25%;
    max-width: 25%;
    background: #fff;
  }
  .fullChat__info .chatUser, .chatUserInfo, .searchForm {
    margin-left: $gridGutterSingle;
    margin-right: $gridGutterSingle;
  }
}

//list of users
.chatList {
  margin-block-start: auto;
  margin-block-end: auto;
  @include panel-list();
}
//item of users list
@include triple-growCenter('.chatUser');
.chatUser {
  &.selected {
    background: $matched-color;
  }
  &__icon {
    overflow: hidden;
    max-width: 17%;
    //margin-right: $gridGutterSingle;
    border-radius: 50%;
  }

  &__txt {
    @include txtTruncate();
    h5 {
      margin: 0 0 .1em;
      line-height: 1;
      font-size: 1.34rem;
      @include txtTruncate();

      + span {
        color: $text-muted;
      }
    }
  }

  &__act {
    text-align: right;
    white-space: nowrap;

    .badge {
      background-color: $danger-color;
    }
  }
  &__time {}
  &__inf {
    display: flex;
    align-items: center;
    justify-content: space-between;

    svg {
      color: $success-color;
    }
  }
}


//left column
.fullChat__search {
  padding: $gridGutterSingle;
}

//right column
$avaSize: 17%;
.fullChat__info .chatUser__icon {
  max-width: $avaSize;
}
.chatUserInfo {
  margin-top: $gridGutterSingle;
  margin-bottom: $gridGutterSingle;
  display: grid;
  grid-template-columns: $avaSize auto;
  grid-auto-rows: min-content;
  grid-row-gap: $gridGutterSingle;
  dt {
    display: flex;
    align-items: center;
    justify-content: center;
  }

  dd {
    margin-inline-start: $gridGutterSingle;
    h5 {
      margin: 0;
      font-size: 1.34rem;
    }
    sup {
      color: $text-muted;
    }
  }
}

@include triple-growCenter('.chatSource', $space-x: 1.63333rem);
.chatSource {
  padding: $grid-gutter-width $gridGutterSingle;
  &:nth-child(odd) {
    background: $matched-color;
  }
}


//CHAT with Messages
.chat {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding-bottom: $gridGutterSingle;
  background-color: $gray-lighter;
  @include border-top-radius($radius-base);
  overflow: hidden;

  &__contact {
    flex: 0 auto;
    padding: $gridGutterSingle;

    h5  {
      margin: 0;
    }
  }
  &__body {
    overflow-y: auto;
    flex: 1 auto;
    padding: $gridGutterSingle
  }
  &__act {
    flex: 0 auto;
  }
  &__act {
    margin-left: $gridGutterSingle;
    margin-right: $gridGutterSingle;
    background: #fff;
  }
}
.chatAct {
  display: flex;
  align-items: center;
  border: $control-border-width solid $control-border-color;
  border-radius: $control-border-radius;

  .form-control {
    border: none;
    resize: block;
  }

  &__input {
    flex: 1 auto;
  }
  &__act {
  flex: 0 auto;
  }
}


@keyframes typing {
  0%, 75%, 100% {
    transform: translate(0, 0.25rem) scale(0.9);
    opacity: 0.5;
  }

  25% {
    transform: translate(0, -0.25rem) scale(1);
    opacity: 1;
  }
}
$chat-radius: 1.25rem;
$chat-paddingY: 0.4em;
$chat-paddingRight: 0.2em;
$chat-paddingLeft: 0.8em;
.msgTime {
  font-size: 0.8rem;
  width: fit-content;
  margin: 1em auto;
  padding: 0.05em 0.7em;
  background: $gray-lighter;
  border-radius: 2em;
  color: #999;

  &:hover {
    background: $gray-light;
  }
}
.msg {
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr auto;

  &:not(.msg--img):not(.msg--media) {
    padding: $chat-paddingY $chat-paddingRight $chat-paddingY $chat-paddingLeft;
  }

  div + & {// not .msg > .msg
    > .mediaCase,
    > .file {
      grid-column: 1/3;
    }
    > .file {
      //width: calc(100% + #{$chat-paddingY});
      margin-top: -$chat-paddingY;
      margin-left: -$chat-paddingY;
      margin-right: -$chat-paddingY;
      padding: $chat-paddingY $chat-paddingY 0;
      background: rgba($color-base-2, .1);
    }
  }
  .msgCase {
    overflow: hidden;
    min-width: 50px;
  }

  &--media,
  &--img {
    padding: $chat-paddingY;
    &:has(.msg--img, .msg--media) {
      > div {
        padding-left: 4px;
        padding-right: 4px;
      }
    }

    img {
      max-width: 100%;
    }
  }

  .mediaCase {
    display: flex;
    align-items: center;
    justify-self: center;

    svg {
      height: 25px;
      width: 25px;
    }
  }

  //min-height: 2.25rem;
  width: fit-content;
  max-width: 66%;
  margin-left: 1em;
  margin-right: 1em;
  border: 1px solid transparent;
  box-shadow: 0 0 .2rem rgba(0, 0, 0, 0.075),
  0rem 0.3rem 0.3rem -0.3rem rgba(0, 0, 0, 0.1);
  background: $white;

  &, .mediaCase, img, video {
    border-radius: $chat-radius;
  }

  &--to + &--from,
  &--from + &--to {
    margin-top: 1.5em;
  }

  &--to + &--to,
  &--from + &--from {
    margin-top: .4em;
  }
  &:has(> .msg--img, > .msg--media) {
    grid-template-columns: minmax(100px, 1fr) 3fr;
    .msg__time {
      grid-column: 1/3;
      margin-top: -1em;
    }
  }
  > .msg {
    &:not(.msg--img):not(.msg--media) {
      width: 100%;
      grid-column: 1 / 3;
      margin-bottom: 0.4em;
    }
    &--img {
    }

    width: 100%;
    max-width: none;
    margin: -$chat-paddingY 0 0;
    font-size: 0.8em;
    box-shadow: none;
    @include txtTruncate();

    .mediaCase {
      min-width: 30px;
      align-items: start;
      &, + .msg__txt {
        @include txtTruncate();
      }
    }
  }
  &.msg--to > .msg {
    border-end-end-radius: 0;
    &--img {
      height: 100px;
      img {
        max-height: 100%;
      }
    }
  }

  &--from {
    &, .mediaCase, img, video {
      border-end-start-radius: $chat-radius / 3;
    }
  }

  &--to {
    margin-inline-start: auto;
    border-end-end-radius: $chat-radius / 3;
    background: $color-base-0-contrast;
    &, .mediaCase, img, video {
      border-color: $color-base-0-contrast;
    }
  }

  //Start seria of messages from contact
  &Time &--to + &--from:has(+ .msg--from),
  &--to + &--from:has(+ .msg--from) {
  }
  &--from + &--from {
    border-start-start-radius: $chat-radius / 3;
  }
  &--from + &--from:last-child,
  &--from + &--from:has( + .msg--to, + .msgTime) {
    border-start-start-radius: $chat-radius / 3;
    border-end-start-radius: $chat-radius;
  }
  //End seria of messages from contact

  //Start seria of messages from me

  &Time + &--to:has(+ .msg--to),
  &--from + &--to:has(+ .msg--to) {
  }
  &--to + &--to {
    &, .mediaCase, img, video {
      border-start-end-radius: $chat-radius / 3;
    }
  }
  &--to + &--to:last-child,
  &--to + &--to:has( + .msg--from, + .msgTime) {
    border-end-end-radius: $chat-radius;
  }
  //End seria of messages from me

  &__time {
    align-self: end;
    padding-left: .5em;
    font-family: ui-monospace;
    font-size: 75%;
    line-height: 0;
    vertical-align: baseline;
    text-align: right; // for msg--img case
    svg {
      width: 1.2em;
      height: 1.2em;
      color: $success-color;
      &.icon--doubleCheck {
      }
    }
  }
  &__txt {

  }

  .typing {
    display: inline-block;
    width: 0.6rem;
    height: 0.6rem;
    margin-right: 0;
    box-sizing: border-box;
    background: #ccc;
    border-radius: 50%;

    &.typing-1 { animation: typing 3s infinite }
    &.typing-2 { animation: typing 3s 250ms infinite }
    &.typing-3 { animation: typing 3s 500ms infinite }
  }

  iframe,
  video {
    max-width: 100%;
  }
}

.file {
  display: grid;
  grid-template-columns: auto 1fr auto;
  grid-template-rows: 1fr 1fr;
  column-gap: 5px;
  align-items: center;

  &__info {
    grid-column: 1/4;
  }

  &__type {
    svg {
      width: 24px;
      height: 24px;
    }
  }
  &__act {
    position: relative;
    svg {
      width: 32px;
      height: 32px;
      //color: initial;
    }
  }


}

.progress-ring {
  &--hidden {
    display: none;
  }

  + a {
    position: absolute;
    left: 0;
    top: 0;
    transform: scale(.7);
  }
}