.add-sections {
  $sectPadding: $padding-x-base / 2;

  > .form-group {
    .side-nav & {
      background: $color-base-0;
      border-radius: $radius-base;
    }

    .side-nav__body & {
      margin-left: -$sectPadding;
      margin-right: -$sectPadding;
      padding: $sectPadding;
    }
  }

  .form-group__label {
    font-size: 1rem;
  }

  .form-group__content {
    min-height: auto;
  }
}

.add-section__plus {
  padding-top: $padding-y-base;
}