// REPORTING PANEL
.panel-reporting {
  + .panel-reporting {
    margin-top: rem(20px);
  }

  .panel__heading {
    .panel-reporting__title {
      font-weight: bold;
      //color: $color-accent-2;
    }
  }
  .panel__heading, .panel__body {
    padding-left: 0 !important;
    padding-right: 0 !important;
  }
  .panel__heading {
    .figure-h {
      width: 100%;
      padding-top: rem(30px);
      padding-bottom: rem(30px);
    }
  }
  .panel__body {
    padding-top: 0 !important;
    padding-bottom: 0 !important;

    .figure-h {
      position: relative;
      width: 100%;
      padding-top: rem(20px);
      padding-bottom: rem(20px);

      + .figure-h {
        border-top: 1px solid $color-base-0;
      }
    }
  }

  &__title {
    display: flex;
    align-items: center;
    margin: 0 0 .5rem;
    .badge {
      margin-left: .9em;
    }
  }

  .panel__heading {
    .panel-reporting__title {
      font-size: 1.3rem;
    }
  }
  .panel__body {
    .panel-reporting__title {
      font-size: 1.2rem;
    }
  }

  &__text {
    color: $color-base-2;
    &:last-child {
      padding-right: rem(46px);
    }
  }
}

//https://prnt.sc/vrdkgy
.reportFiltersPanel {
  > * {}
  &__content {
    &.section-box {
      padding-bottom: 0;
    }
  }
}
/*Reconcilation Report start*/
.reconcilation_report {
  .budget-sheet-table__header {
    top: $contentHeight;
    top: $reportingFiltersSpace + $panel-padding * 2;
  }
  .budget-sheet-table {
    margin-top: ($reportingFiltersSpace + $panel-padding);
  }
}


