// Common
.simple-text {
  line-height: 1.8;
}

.stripePayment,
.signUpStep {
  .lean-overlay {
    top: 0 !important;
    bottom: 0 !important;
    height: 100%;
    filter: blur(6.4px);
    background: url("../images/bg-signUpSteps--16x9.png") no-repeat 0 0/cover;

    ///* (1440x900) WXGA+ Display */
    @media screen and (max-width: 1440px) {
      background-image: url("../images/bg-signUpSteps--1.6x1.png");
    }
    ///* (1280x1024) SXGA Display */
    @media screen and (max-width: 1280px) {
      background-image: url("../images/bg-signUpSteps--1.25x1.png");
    }
    ///* (1024x768) iPad 1 & 2, XGA */
    @media only screen and (min-device-width: 768px) and (max-device-width: 1024px) {
      background-image: url("../images/bg-signUpSteps--4x3.png");
    }
  }
}
.lean-overlay {
  //cursor: url('data:image/png;base654,'), auto;
}
//url("/mainStyles/new-ui/images/")
.sign-up-step {
  .modal-header {
    h1 {
      margin: 0;
    }
    .visual img {
      max-height: 200px;
    }
  }
  .modal-wrapper {
    > *:first-child {
      padding-top: $modal-padding-y + rem(15px);

    }
    > *:last-child {
      padding-bottom: $modal-padding-y + rem(15px);
    }
  }
  &--1 {
    text-align: center;

    .modal-header {
      figure {
        margin: 0;
        .visual {
        }
      }
      figcaption {
        margin-top: 30px;
      }
    }

    .modal-content {
      p {
        font-size: rem(14px);
      }
      a[href^=mailto] {
        color: $text-color-base;
      }
    }
  }
  &--2 {
    .modal-wrapper {
      padding-right: 30%;
      background: #fff url('../icons//sign-up-step-password.svg') 100% 50% / auto 80% no-repeat;
      background-position: right 20px bottom 30px;
    }
    .modal-header {
      text-align: left;
    }
  }
  &--3,
  &--4 {
    .modal-header {
      padding-bottom: 32px;
      &:after {
        top: auto;
        bottom: 0;
        height: 0;
        right: $modal-padding-x;
        left: $modal-padding-x;
        border-bottom: 1px solid $gray-new;
      }
    }
  }
  &--3 {
    .modal-content {
      position: relative;
      padding-right: 33%;

      &:after {
        content: '';
        position: absolute;
        top: 15px;
        bottom: 0;
        right: 0;
        width: 33%;
        background: url('../icons/sign-up-step-org.svg') 50% 100%/contain no-repeat;
      }

    }
  }
  &--4 {
  }
  &__section {
    //margin-bottom: 20px;
    //padding-bottom: $modal-padding-y;

    //+ h3 {
    //  font-weight: 500;
    //}
  }
  .sub-title {
    font-weight: 500;
  }

  .modal-footer {
    flex-wrap: wrap;
    border-top: none;

    .footnote {
      flex: 100% 0 0;
      padding-top: 20px;
    }
  }

  .cp_modules-switch {
    flex-wrap: nowrap;
  }
  &__password {
    padding-right: 60px;

    .form-group__content {
      position: relative;
    }
    .form-control {
      padding-right: 74px;
    }
    .pass-validation {
      position: absolute;
      left: 100%;
      top: 0;
      margin: 0 0 0 -74px;
      width: 140px;
      justify-content: flex-start;
      white-space: nowrap;
    }
  }
}
