$modal-padding-x: rem(30px);
$modal-padding-y: rem(25px);

.modal-holder.active {
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  &.wg_dial__parent {
    align-items: flex-end;
    justify-content: flex-end;
  }
  .modal {
    z-index: 1003;
  }
  .lean-overlay {
    z-index: 1002;
  }
}
.modal {
  min-width: 300px;
  max-width: 75%;
  max-height: 90%; //https://prnt.sc/qapir5
  @extend .z-depth-1-half;
  background-color: $white;
  border: 1px solid rgba($color-base-1, .2);
  border-radius: $radius-base;
  will-change: top, opacity;

  &.vat-special-modal {
    max-width: 900px;
    width: 100%;

    .modal-header {
      text-align: left;
      .modal-header-heading {
        font-weight: 700;
        font-size: 20px;
        line-height: 24px;
        color: #425364;
      }
    }
  }

  .modal-footer {
    border-top: 0;
  }

  .vat-modal-list {
    font-weight: 500;
    font-size: 12px;
    line-height: 15px;
    color: #5A6169;
    padding-left: 15px;
    li {
      list-style: disc;
      margin-bottom: 15px;
    }
  }

  .vat-modal-row {
    display: flex;
    justify-content: space-between;
  }

  .vat-modal-column-small {
    width: 284px;
    padding-left: 24px;
    border-left: 1px solid #C4D0DA;
  }

  .vat-modal-column-large {
    padding-right: 24px;
  }

  .vat-conditions-area {
    margin-top: 24px;
  }

  .modal-content {
    padding-bottom: 0;
  }

  .vat-modal-item {
    .form-group {
      background: #F4F7FA;
      border-radius: 3px;
      padding: 10px;

      .form-group__label {
        margin-top: 12px;
        text-transform: unset;
      }

      input.form-control.default-width {
        width: 50%;
      }
    }
  }

  .vat-modal-inner-heading {
    font-size: 14px;
    font-weight: 500;
    color: #1D252C;
    margin-top: 0;

    strong {
      font-weight: 700;
    }
  }
}
.modal {
  ::-webkit-scrollbar {
    /*display: block;*/
  }

  h1, h2, h3, h4 {
    //margin-top: 0;
  }

  .modal-close {
    cursor: pointer;
  }

  &-wrapper {
    display: flex !important;
    flex-direction: column;
    height: 100%; // need for scrolled child blocks (.kpi-upload)


    @media #{$medium-and-down} {
      width: 80%;
    }
  }
  &--md {
    max-width: 85%;
  }

  &[style*="width: 400px"] {
    .modal-wrapper {
      width: 400px;
    }
  }

  &-header,
  &-footer,
  &-content {
    background-color: #fff;
  }

  &-header,
  &-footer {
    padding-left: $modal-padding-x;
    padding-right: $modal-padding-x;
  }

  &-header {
    position: relative;
    flex-shrink: 0;
    font-size: 20px;
    text-align: center;
    font-weight: bold;
    color: #425364;
    padding-top: $modal-padding-y;
    @include border-top-radius($radius-base);

    &:after {
      left: 0;
      right: 0;
      @extend .gradient-blend-top--white;
    }

    .modal-light & {
      padding: 10px 10px 0;
    }
  }

  &-content {
    overflow-y: auto;
    padding: $modal-padding-y rem(30px);
    .has-material-carousel & {
      padding: 0;
    }


    > .form-group:last-child {
      margin-bottom: 0; //https://prnt.sc/t38qio
    }

    > table {
      width: 100% !important; /*to prevent horizontal scroll*/
    }
    .wfmMessageBox td {
      text-align: center;
    }

    .modal-light & {
      *:first-child { //for h5
        margin-top: 0;
      }
      p:last-child {
        margin-bottom: 0;
      }
      h5 {

      }
    }
  }

  &-footer {
    @include border-bottom-radius($radius-base);
    display: flex;
    flex-direction: row-reverse;
    justify-content: center;
    flex-shrink: 0;
    padding-top: rem(15px);
    padding-bottom: rem(15px);
    border-top: 1px solid #D8D8D8;
    background-color: #fff;

    .modal-light & {
      border-top: none;
      padding-top: 0;
    }

    &.text-left {
      justify-content: flex-end;
      > .btn:last-child {
        margin-left: 0;
      }
      > .btn:first-child {
        margin-left: 0;
      }
    }
    //&.buttons-opposite {
    //  justify-content: space-between;
    //  > .btn {
    //    margin-left: 0;
    //    margin-right: 0;
    //  }
    //}
    > .btn {
      min-width: 80px; // make "save" and "cancel" buttons equal size
    }

    > .btn,
    > .dropdown-split {
      margin: 0 5px 5px;
    }

  }


  //Guide Line Modal
  .has-guide-modal & {
    position: fixed;
    //top: 10% !important;
    //bottom: 10%;
    top: 5% !important;
    left: 10%;
    right: 10%;
    width: auto !important;
    //height: auto !important;

    @media screen and (max-width: 1366px) {
      max-width: 740px;
    }

    .modal-wrapper {
      position: relative;
      overflow: visible;
      height: auto !important;
    }
    .modal-content {
      position: relative;
      padding-bottom: 54.65%; /* 16:9 */
      padding-top: 25px;
      height: 0;
      
      @media screen and (max-width: 1366px) {
        padding-bottom: 53.05%;
      }
      
      iframe {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
      }
    }
    .btn--close {
      position: absolute;
      z-index: 9;
      top: -($button-height-small / 2);
      right: -($button-height-small / 2);
      background: black;
      color: #fff;
      opacity: 1;
    }
  }
}

.lean-overlay {
  position: absolute;
  //z-index: 999;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  width: 100%;
  will-change: opacity;
  background: rgb(141, 155, 168);

  &[style*="1002"] {
    ~ .dropdown-content.select-dropdown.active {
      //z-index: 1003;// was used before, when .lean-overlay was in > body
    }
  }
}
.modal[style*="1003"] {
  ~ .dropdown-content.select-dropdown.active {
    //z-index: 1004;
  }
}

// Modal with fixed action footer
.modal.modal-fixed-footer {
  padding: 0;
  height: 70%;

  .modal-content {
    position: absolute;
    height: calc(100% - 56px);
    max-height: 100%;
    width: 100%;
    overflow-y: auto;
  }

  .modal-footer {
    border-top: 1px solid rgba(0, 0, 0, .1);
    position: absolute;
    bottom: 0;
  }
}

// Modal Bottom Sheet Style
.modal.bottom-sheet {
  top: auto;
  bottom: -100%;
  margin: 0;
  width: 100%;
  max-height: 45%;
  border-radius: 0;
  will-change: bottom, opacity;
}

//MODAL WITH WITE BG
.has-modal--sampledata {
  .lean-overlay {
    opacity: 0.8 !important;
    background: #fff;
  }
}

.modal--sample {
  .modal-wrapper {
    background: rgba(255, 255, 255, 0.84);
    box-shadow: 0px 20px 40px 0 rgba(0, 0, 0, 0.06);
    border-color: lighten($color-base-1, 8%);
    border-color: $color-base-0;
  }
  .modal-header {
    h5 {
      margin: 0;
      font-size: 17px;
    }
    p {
      &:last-child {
        margin-bottom: 0;
      }
    }
  }
  .modal-content {
    padding-top: 10px;
  }
  .btns-group + .img-holder {
    margin-top: 20px;
  }
}
.modal--sample-image {
  .modal-content {
    margin-bottom: 0;
    padding-bottom: 0;
  }
}
.modal-sample-intro {
  .modal-content {
    @media screen and (max-width: 1366px) {
      padding-top: 0;
    }
    p {
      margin: rem(9px) 0;
      font-size: rem(13px);
    }
  }

}
.modal-chooseOptions {
  .modal-content {
    .gwt-RadioButton + * {
      margin-top: 10px;
    }
  }
}

