//CRM > CALLENDAR MODAL
.close-x {
  display: flex;
  align-items: center;
  justify-content: center;

  @include close-button;
}
.cal-popup {
  padding: 15px;
  border-radius: $radius-base;
  background-color: #fff;
  box-shadow: 0px 3px 14px 0px rgba(0, 0, 0, 0.3);
  border: 1px solid $color-base-1;
  //.close-button,
  .close-x {
    position: absolute;
    z-index: 1;
    right: 7px;
    top: 7px;
    cursor: pointer;
  }

  a:hover {
    text-decoration: underline;
  }

  .popupContent {
    > div > table > tbody > tr {
      + tr {
        > td {
          padding-top: 10px;
        }
      }
    }
  }
}
.popup-overlay {
  top: 0;
  bottom: 0;
  right: 0;
  left: 0;

  border-radius: $radius-base;
  //background-color: transparent;
  //transition: background-color .3s ease;
  .frame__content & {
    right: $frameContentPadding;
    bottom: $frameContentPadding;
  }
  .cal-popup--opened & {
    position: absolute;
    //background-color: rgba(#8c8c8c,.1);
  }
}


