%form-control-size {
  //box-sizing: border-box;
  white-space: nowrap;
  height: $input-height;
  line-height: $input-btn-line-height;
}
%form-control-size-small {
  height: $button-height-small;
  line-height: $button-line-height-small;
  font-size: $button-font-size-small;
}
%form-control-size-medium {
   height: $button-height-medium;
   line-height: $button-line-height-medium;
   font-size: $button-font-size-medium;
 }
%form-control-size-large {
  height: $button-height-large;
  line-height: $button-line-height-large;
  font-size: $button-font-size-large;
}

%form-control-style {
  @include form-control-style();
}

.from-control--action {
  &.active,
  &:hover {
    box-shadow: 0 8px 27px 0 rgba(176, 186, 195, 0.33);
  }
}

.btn-default--action { // Used for btn "+" upload-file
  transition: border-color .1s ease;
  &:hover {
    border-color: $button-border-color-default-hover;
  }
}


.dropdown-content-size {
  @include dropdown-content-size;
  //overflow-y: auto;
  clear: both;
  position: absolute;
  //z-index: 999; // It hinders the z-index of arrows (:befor, :after)
  min-width: 60px; //ToDo check it Decreased by Murad Demands (settings panel page size dropdown)
  //max-height: 350px; //decreased by Normurod request // and removed by Evgeniy request because there are lists with lots options, and they dont fit into this height.
  // Oveflow to make scroll also not possible because there might be multilevel lists
  margin: 0;
  will-change: width, height;

  max-height: 420px;
  @media screen and (max-height: 900px) {
    max-height: 370px;
  }
  @media screen and (max-height: 768px) {
    max-height: 320px;
  }
  .operPanel & {
    max-height: 84vh;
  }
}


// COMMON LABELS
@mixin form-label() {
  min-height: 13px; // To force enpty label work as placeholder
  text-transform: uppercase;
  font-weight: 500;
  font-size: rem(9px);
  color: $text-color-base;
}
.form-label {
  @include form-label();
  display: block;
  margin:0 0 rem(6px);
}