/***************
     Switch
***************/
$switcherWidth: 45px;
$switcherHeight: 20px;
$switcherLeverSize: 14px;
$switcherLeverGap: 3px;


.switch,
.switch * {
  -webkit-user-select: none;
  -moz-user-select: none;
  -khtml-user-select: none;
  -ms-user-select: none;
}

.switch label {
  cursor: pointer;
}

.switch label input[type=checkbox]{
  opacity: 0;
  width: 0;
  height: 0;
  position: absolute;
  z-index: -100;
}

.switch label input[type=checkbox]:checked + .lever {
  background-color: $switch-checked-lever-bg;
}

.switch label input[type=checkbox]:checked + .lever:after {}

.switch label .lever {
  content: "";
  display: inline-block;
  position: relative;
  width: $switcherWidth;
  height: $switcherHeight;
  //border: 1px solid $color-base-lighten;
  border-radius: $switcherHeight / 2;
  transition: background 0.3s ease;
  vertical-align: middle;
  background-color: $switch-unchecked-lever-bg;

  &:after {
    content: "||";
    text-indent: 1px;
    position: absolute;
    top: 50%;
    left: $switcherLeverGap;
    display: inline-block;
    width: $switcherLeverSize;
    height: $switcherLeverSize;
    margin-top: -($switcherLeverSize / 2);
    line-height: $switcherLeverSize;
    background-color: $switch-unchecked-bg;
    text-align: center;
    color: $color-base-0;
    border-radius: 50%;
    transition: left 0.3s ease, border-color .3s ease;
  }
}
.switch__label--left:not(:empty) {
  margin-right: rem(10px);
}
.switch__label--right:not(:empty) {
  margin-left: rem(10px);
}

// Switch active style
input[type=checkbox]:checked:not(:disabled) ~ .lever:active:after {}

input[type=checkbox]:not(:disabled) ~ .lever:active:after {}
.switch label input[type=checkbox]:checked + .lever {}

.switch label input[type=checkbox]:checked + .lever:after {
  left: ($switcherWidth - $switcherLeverSize - $switcherLeverGap);
}

// Disabled Styles
.switch input[type=checkbox][disabled] + .lever{
  cursor: default;
}
.switch label input[type=checkbox][disabled] + .lever:after,
.switch label input[type=checkbox][disabled]:checked + .lever:after {
  //background-color: $input-disabled-solid-color;
}