// PAGING
.paging {
  display: inline-flex;
  align-items: center;
  margin: 0;

  > li {
    + li {
      margin-left: 0;
    }
  }
  .gwt-TextBox {
    text-align: center !important;
  }

  .btn {
    border-radius: 0;
    border: none;
  }

  &__prevpage {
    .btn {
      @include border-left-radius($radius-base)
    }
  }
  &__nextpage {
    .btn {
      @include border-right-radius($radius-base)
    }
  }
  &__currentpage {
    .form-control,
    .gwt-TextBox {
      border: none;
      border-radius: 0;
      text-align: center !important;
    }
  }
}
// \ PAGING


// PAGING STAT
.pagingStat {
  @extend %form-control-size;
  @include form-control-style(transparent);
  @extend .btn--white;
  white-space: nowrap;
  display: flex; // because this is the <span> el
  align-items: center;
  //padding: 0 15px;
  //padding: rem(0 15px);
  //height: $button-height;
  //line-height: $button-line-height;
  //background: white;
  //white-space: nowrap;
  //text-align: center;

  .paging-group & {
    @include border-radius($radius-base 0 0 $radius-base);
  }

  &__wrapper {
    position: relative;
    .dropdown-content {
      top: 100% !important;

      .attendanceReport__bottom-bar & {
        top: auto !important;
        bottom: 100% !important;
      }
    }
  }
}

.operPanel .pagingStat span {
  display: block;

  &:empty:after {
    content: '\00a0';
    display: inline;
  }
}






.paging-group {
  display: flex;
  &.text-right {
    justify-content: end;
  }

  &__wrapper {
    border-color: transparent !important;
  }

  > * {
    display: flex;
  }

  .dropdown-button {
    box-shadow: none !important;
    &:focus,
    &:hover {
      box-shadow: none !important;
    }
  }

  .paging > li:first-child {}

  .paging__prevpage {
    .btn {
      @include border-left-radius(0)
    }
  }
}