.attendanceReport__table-wrapper {
  padding-top: $theadHeight;
}


.attendanceReport__filters.fixed-content {
  z-index: 100;
}

.attendanceReport__table-body td.inhour-overtime,
.attendanceReport__table-header th.inhour-overtime {
  background: #FFF;
  color: black !important;
  font-weight: bold;
  padding: 0 !important;
  text-align: center !important;
}

.attendanceReport {
  .frame_affix_top { //https://i.imgur.com/syWBhLR.png
    .attRep-date {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
    }
    span {
    }
  }

  td.inhour-overtime,
  th.inhour-overtime{
    width: 100px !important;
  }

  td span {
    display: inline-block;
    padding: 5px 8px;
  }

  #attendanceTableBeta {
    min-width: 100%;
    width: 2220px !important;
    background: #FFF;
  }

  .attendanceReport__table-header.fixed-content {
    position: sticky !important;
    top: 0;
  }

  .attendanceReport__table-wrapper td:first-child,
  .attendanceReport__table-wrapper th:first-child{
    position: sticky !important;
    left: 0;
    background: #fff;
    z-index: 8;
    text-align: left;
    padding-left: 20px;
  }

  .attendance-image {
    width: 35px;
    height: 35px;
    float: left;
    margin-right: 10px;
    //object-fit: cover;
    border-radius: 50%;
    background-size: cover;
    background-position: center;
    overflow: hidden;
    position: relative;
    &::after {
      position: absolute;
      z-index: -1;
      left: 0;
      right: 0;
      top: 0;
      bottom: 0;
      content: '';
      background-image: url(data:image/png;base64,);
      background-size: 35px 35px;
      background-position: center;
      border-radius: 50%;
    }
  }

  th.inhour-overtime.stickerCell {
    width: 100px !important;
  }

  .attendanceReport__table-wrapper {
    padding-top: 0;
  }
}



.attendanceReport .attendanceReport__table-wrapper .attendance-report-collapsible-table td:not(.attendance-report-collapsible-table-grouped-column):first-child,
.attendanceReport .attendanceReport__table-wrapper .attendance-report-collapsible-table th:first-child {
  position: static !important;
}

#totalLeaveType tr td:first-child:empty + td {
  text-align: left;
  padding-left: 20px;
}

.attendanceReport td span.attendance-report-employee-name {
  display: block !important;
  padding: 0 !important;
}

.attendanceReport td span.attendance-report-employee-tooltip {
  position: absolute;
  background: #1D252C;
  color: #FFF;
  left: calc(100% + 17px);
  top: 0;
  //max-width: calc(100% - 4px);
  min-height: 36px;
  line-height: 120%;
  padding: 10px 8px;
  border-radius: 2px;
  transform: translateX(-10px);
  opacity: 0;
  visibility: hidden;
  transition: 300ms;
  &:empty {
    display: none;
  }
}

.attendanceReport td span.attendance-report-employee-name:hover > span.attendance-report-employee-tooltip {
  opacity: 1;
  visibility: visible;
  transform: translateX(0);
}

.attendanceReport .attendanceReport__table-wrapper tbody#attendanceReportScrollTableTbody tr:last-child td:first-child {
  //position: static !important;

  span.attendance-report-employee-tooltip {
    top: auto;
    bottom: 0;
  }
}


.attendanceReport td span:not(.attendance-report-employee-tooltip):first-child {
  transform: rotate(-45deg) translate(-50%,-50%);
  width: 100%;
  text-align: center;
  padding: 5px 0;
  position: absolute;
  top: 50%;
  left: 50%;
  margin-top: -30px;
  margin-left: -5px;
}

.attendanceReport td {
  position: relative;
}

.attendanceReport td span + span {
  position: absolute;
  right: 0;
  bottom: 0;
}

.attendanceReport td span:not(.attendance-report-employee-tooltip):first-child:last-child {
  position: absolute;
  margin: 0;
  width: unset;
  padding: 5px 8px;
  left: 50%;
  top: 50%;
  transform: translate(-50%,-50%);
}

.attendanceReport td .attendance-report-employee-tooltip span:first-child {
  transform: none;
  position: static;
  padding: 5px 8px;
  text-align: left;
  margin: 0;
}


attRep-date {
  &__month {}
  &__day {}
}
.attRep-date_weekday {
  display: block;
  opacity: 0.8;
  font-weight: normal;
}

.attendance_report_modal {
  .modal-content table tr:first-child td {
    padding-bottom: 10px;
  }
}
