.hero-input {
  background-color: #F7F9FA;
  border-radius: 8px;
  min-height: 60px;
  position: relative;

  &--text {
    background-color: white;
  }

  [class*="dropdown-kit--"] {
    z-index: 3;
    font-weight: normal;
  }

  .form-control {
    border: none;
    background-color: transparent;
  }
  &.hero-input--select {
    .dropdown-content.select-dropdown {
      right: 0 !important;
      width: auto !important;
      height: auto !important;
      padding: 0 !important;
    }
  }
}

.hero-input + .hero-input {
  margin-top: 10px;
}

.hero-input__label {
  position: absolute;
  top: 10px;
  left: 24px;
  right: 24px;
  display: block;
  font-size: 12px;
  color: $color-accent-2;
}

.hero-input--text input,
.hero-input--select .gwt-ListBox input.select-dropdown {
  //.hero-input--select select,
  //.hero-input--select .select2-container--default .select2-selection--single .select2-selection__rendered {
  padding: 27px 24px 5px 24px;
  border: none;
  border-radius: 8px;
  display: block;
  width: 100%;
  box-sizing: border-box;
  line-height: 30px;
  height: auto;
  font-size: 15px;
  outline: none;
  background-color: transparent;
  color: $color-accent-2;
}

.hero-input--text.hero-input--suffix input {
  padding-right: 150px;
}

.hero-input--text .hero-input__label {
  cursor: text;
}

.hero-input__suffix {
  font-size: 15px;
  font-weight: bold;
  position: absolute;
  right: 20px;
  bottom: 7px;
}

.hero-input--select .select2-container--default .select2-selection--single {
  border: none;
  background-color: transparent;
  outline: none;
}

.hero-input--select .select2-container--default .select2-selection--single .select2-selection__arrow {
  right: 10px;
}